            def __init__(self, root):
                self.root=root
                self.rows={}
            @contextmanager
            def _transaction(self, *args):
                yield
            def _read(self, path):
                return self.rows.get(str(path))
            def _write_atomic(self, path, value):
                self.rows[str(path)]=value

        store=Store(tmp_path)
        service=SimpleNamespace(store=store)
